<?php
declare(strict_types=1);require_once __DIR__.'/includes/functions.php';require_login();$uid=(int)current_user()['id'];$recipeToAdd=(int)($_GET['recipe_id']??$_POST['recipe_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='create_folder'){$name=trim($_POST['name']??'');if($name!==''&&mb_strlen($name)<=80){db()->prepare('INSERT INTO bookmark_folders(user_id,name) VALUES(?,?)')->execute([$uid,$name]);audit('BOOKMARK_FOLDER_CREATE',null,$name);flash('success','Collection created.');}else flash('error','Collection name is required.');}
 elseif($action==='add_bookmark'){$folder=(int)($_POST['folder_id']??0);$rid=(int)($_POST['recipe_id']??0);$stmt=db()->prepare('SELECT 1 FROM bookmark_folders WHERE id=? AND user_id=?');$stmt->execute([$folder,$uid]);if($stmt->fetchColumn()&&$rid){db()->prepare('INSERT IGNORE INTO bookmarks(user_id,folder_id,recipe_id) VALUES(?,?,?)')->execute([$uid,$folder,$rid]);audit('BOOKMARK_ADD',$rid,'Folder '.$folder);flash('success','Recipe added to your collection.');$recipeToAdd=0;}}
 elseif($action==='remove_bookmark'){$bid=(int)($_POST['bookmark_id']??0);db()->prepare('DELETE FROM bookmarks WHERE id=? AND user_id=?')->execute([$bid,$uid]);flash('success','Bookmark removed.');}
 redirect('bookmarks.php'.($recipeToAdd?'?recipe_id='.$recipeToAdd:''));
}
$stmt=db()->prepare('SELECT bf.*,COUNT(b.id) item_count FROM bookmark_folders bf LEFT JOIN bookmarks b ON b.folder_id=bf.id WHERE bf.user_id=? GROUP BY bf.id ORDER BY bf.created_at');$stmt->execute([$uid]);$folders=$stmt->fetchAll();
$stmt=db()->prepare('SELECT b.id bookmark_id,b.folder_id,bf.name folder_name,r.*, (r.prep_minutes+r.cook_minutes) total_minutes, COALESCE(AVG(rt.rating),0) avg_rating, COUNT(DISTINCT f.id) favorite_count FROM bookmarks b JOIN bookmark_folders bf ON bf.id=b.folder_id JOIN recipes r ON r.id=b.recipe_id LEFT JOIN ratings rt ON rt.recipe_id=r.id LEFT JOIN favorites f ON f.recipe_id=r.id WHERE b.user_id=? AND r.status="approved" GROUP BY b.id,r.id ORDER BY b.created_at DESC');$stmt->execute([$uid]);$items=$stmt->fetchAll();
$pageTitle='Saved recipes';require __DIR__.'/includes/header.php';?>
<section class="section container"><div class="section-heading"><div><span class="eyebrow">Personal cookbook</span><h1>Your saved recipes</h1><p>Organise recipes into collections for meal ideas, occasions or dietary goals.</p></div></div>
<?php if($recipeToAdd):?><div class="panel callout-panel"><h2>Save recipe to a collection</h2><?php if(!$folders):?><p>Create your first collection below, then return to save the recipe.</p><?php else:?><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="add_bookmark"><input type="hidden" name="recipe_id" value="<?=$recipeToAdd?>"><label>Collection<select name="folder_id" required><?php foreach($folders as $folder):?><option value="<?=$folder['id']?>"><?=e($folder['name'])?></option><?php endforeach;?></select></label><button class="button button-primary">Save here</button></form><?php endif;?></div><?php endif;?>
<div class="bookmarks-layout"><aside><div class="panel"><h2>Collections</h2><div class="folder-list"><?php foreach($folders as $folder):?><a href="#folder-<?=$folder['id']?>"><span>▣ <?=e($folder['name'])?></span><small><?=$folder['item_count']?></small></a><?php endforeach;?></div><form method="post" class="form-stack compact-form"><?=csrf_field()?><input type="hidden" name="action" value="create_folder"><label>New collection<input name="name" maxlength="80" required placeholder="e.g. Weeknight dinners"></label><button class="button button-secondary">Create collection</button></form></div></aside><div><div class="saved-list"><?php if(!$items):?><div class="empty-state"><h3>No bookmarks yet</h3><p>Open any recipe and choose “Save to collection”.</p><a class="button button-primary" href="<?=e(url('browse.php'))?>">Discover recipes</a></div><?php endif;?><?php foreach($items as $r):?><article class="saved-row" id="folder-<?=$r['folder_id']?>"><img src="<?=e(recipe_image($r['cover_image']))?>" alt=""><div><span class="tag"><?=e($r['folder_name'])?></span><h3><a href="<?=e(url('recipe.php?id='.$r['id']))?>"><?=e($r['title'])?></a></h3><p><?=e($r['cuisine'])?> · <?=$r['total_minutes']?> min · <?=number_format((float)$r['avg_rating'],1)?> ★</p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove_bookmark"><input type="hidden" name="bookmark_id" value="<?=$r['bookmark_id']?>"><button class="icon-button" title="Remove bookmark">×</button></form></article><?php endforeach;?></div></div></div></section>
<?php require __DIR__.'/includes/footer.php';?>
